<?php
declare(strict_types=1);$active_module='discounts';require_once __DIR__.'/layout.php';$u=$supplier_user;$pdo=db();$q=$pdo->prepare('SELECT id,name FROM properties WHERE supplier_id=? ORDER BY name');$q->execute([$u['supplier_id']]);$props=$q->fetchAll();$error='';if($_SERVER['REQUEST_METHOD']==='POST'){$property=(int)($_POST['property_id']??0);$from=$_POST['start_date']??'';$to=$_POST['end_date']??'';$type=$_POST['discount_type']??'percent';$value=(float)str_replace(',','.',$_POST['discount_value']??0);if(!$property||!$from||!$to||$from>$to||$value<=0||!in_array($type,['percent','fixed'],true))$error='İndirim bilgilerini kontrol edin.';else $pdo->prepare('INSERT INTO supplier_discounts(supplier_id,property_id,start_date,end_date,discount_type,discount_value,currency) VALUES(?,?,?,?,?,?,?)')->execute([$u['supplier_id'],$property,$from,$to,$type,$value,$_POST['currency']??'EUR']);}$q=$pdo->prepare('SELECT d.*,p.name FROM supplier_discounts d JOIN properties p ON p.id=d.property_id WHERE d.supplier_id=? ORDER BY d.id DESC');$q->execute([$u['supplier_id']]);$rows=$q->fetchAll();supply_start('Kampanya & indirimler',$active_module);?><section class="page-intro"><p>Tarih aralığına yüzde veya sabit fiyat indirimi tanımlayın. İndirimler acente satış fiyatına otomatik uygulanır.</p></section><?php if($error):?><p class="login-error"><?=htmlspecialchars($error)?></p><?php endif;?><form method="post" class="supply-form"><div class="form-row"><label>Ürün<select name="property_id"><?php foreach($props as $p):?><option value="<?=$p['id']?>"><?=htmlspecialchars($p['name'])?></option><?php endforeach;?></select></label><label>İndirim türü<select name="discount_type"><option value="percent">Yüzde (%)</option><option value="fixed">Sabit tutar</option></select></label></div><div class="form-row"><label>Başlangıç<input type="date" name="start_date" required></label><label>Bitiş<input type="date" name="end_date" required></label><label>Değer<input type="number" name="discount_value" step="0.01" min="0.01" required></label><label>Para birimi<select name="currency"><option>EUR</option><option>TRY</option><option>USD</option></select></label></div><button>İndirimi aktif et</button></form><section class="next-module"><h2>Aktif kampanyalar</h2><?php foreach($rows as $r):?><p><b><?=htmlspecialchars($r['name'])?></b> · <?=htmlspecialchars($r['start_date'])?>–<?=htmlspecialchars($r['end_date'])?> · <?=htmlspecialchars($r['discount_value'])?> <?= $r['discount_type']==='percent'?'%':htmlspecialchars($r['currency'])?></p><?php endforeach;?></section><?php supply_end(); ?>
